-- Preserve existing team, scout, and completed-report deletion behavior.
ALTER TABLE "TrainingSession" DROP CONSTRAINT "TrainingSession_sourceTeamNumber_fkey", ADD CONSTRAINT "TrainingSession_sourceTeamNumber_fkey" FOREIGN KEY ("sourceTeamNumber") REFERENCES "RegisteredTeam" ("number") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "TrainingAttempt" DROP CONSTRAINT "TrainingAttempt_sessionUuid_fkey", ADD CONSTRAINT "TrainingAttempt_sessionUuid_fkey" FOREIGN KEY ("sessionUuid") REFERENCES "TrainingSession" ("uuid") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "TrainingAttempt" DROP CONSTRAINT "TrainingAttempt_scouterUuid_fkey", ADD CONSTRAINT "TrainingAttempt_scouterUuid_fkey" FOREIGN KEY ("scouterUuid") REFERENCES "Scouter" ("uuid") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ScoutReportInProgress" DROP CONSTRAINT "ScoutReportInProgress_sourceTeamNumber_fkey", ADD CONSTRAINT "ScoutReportInProgress_sourceTeamNumber_fkey" FOREIGN KEY ("sourceTeamNumber") REFERENCES "RegisteredTeam" ("number") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ScoutReportInProgress" DROP CONSTRAINT "ScoutReportInProgress_scouterUuid_fkey", ADD CONSTRAINT "ScoutReportInProgress_scouterUuid_fkey" FOREIGN KEY ("scouterUuid") REFERENCES "Scouter" ("uuid") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ScoutReportInProgress" DROP CONSTRAINT "ScoutReportInProgress_trainingSessionUuid_fkey", ADD CONSTRAINT "ScoutReportInProgress_trainingSessionUuid_fkey" FOREIGN KEY ("trainingSessionUuid") REFERENCES "TrainingSession" ("uuid") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ScoutReportInProgress" DROP CONSTRAINT "ScoutReportInProgress_finalizedReportUuid_fkey", ADD CONSTRAINT "ScoutReportInProgress_finalizedReportUuid_fkey" FOREIGN KEY ("finalizedReportUuid") REFERENCES "ScoutReport" ("uuid") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "ScoutReportInProgress" DROP CONSTRAINT "ScoutReportInProgress_attempt_identity_fkey", ADD CONSTRAINT "ScoutReportInProgress_attempt_identity_fkey" FOREIGN KEY ("trainingAttemptUuid", "trainingSessionUuid", "scouterUuid") REFERENCES "TrainingAttempt" ("uuid", "sessionUuid", "scouterUuid") ON DELETE CASCADE ON UPDATE CASCADE;
